//! The complete study argument. This is editorial material, not product policy.

use super::super::super::{charts, escape, number};
use super::super::{Publication, Quantity, Result, case_html, q, table, value};
use std::collections::BTreeMap;
use std::path::Path;

pub(super) fn pages(
    p: &Publication,
    public: &Path,
    correction: String,
) -> Result<Vec<(&'static str, String)>> {
    let mut pages = Vec::new();
    pages.push(("Making work land", format!("<p class=\"kicker\">A field guide to a self-hosting Rust appliance</p><h1>Making<br>work land.</h1><p class=\"deck\">Completion is a workflow transition.<br>Landing is an evidence boundary.<br>Continuity is neither.</p><div class=\"stats\"><div class=\"stat\"><strong>{}</strong><span>distinct selected deliveries · Q01</span></div><div class=\"stat\"><strong>{}</strong><span>eligible non-review admissions · Q05</span></div><div class=\"stat\"><strong>{}</strong><span>ordered finding histories · Q14</span></div></div><p class=\"lede\">A month of admitted public work, read through the task journal, correction circuit, Git boundaries and lane lifecycle—not through a productivity score.</p><div class=\"columns\"><p>Delivery window: {} to {}.<br>Frozen evidence horizon: {}.<br>Calendar: UTC.</p><p>One saved population. Complete sanitized tables. Separate private provenance. No claim of causal speedup or independent review from a clean label alone.</p></div><p class=\"limit\">Read this guide alongside tables.html. The offline HTML is the normative accessible edition; the PDF is the portrait print edition. Report-local aliases reduce disclosure, not outside-information re-identification risk.</p>", value(p,"Q01","Selected"), q(p,"Q06").denominator, value(p,"Q14","Any recorded finding"), p.first_delivery_day, p.last_delivery_day, p.horizon_day)));

    pages.push(("Population and reading rules", page("Scope / 01", "One cohort. Several denominators.", &format!("<p class=\"lede\">The delivery cohort answers what had completed. Admission populations answer what happened after work entered. They are not interchangeable.</p>{}<div class=\"columns\"><section><h3>Selected delivery</h3><p>The latest 1,500 distinct completed births at the frozen horizon. A reopened task has to complete again. Deletion is not delivery. The independently captured board census agrees with every selected identity and all reconstructed completions.</p></section><section><h3>Admission exposure</h3><p>Phase comparisons use non-review claims admitted in the delivery calendar window, with a common 24-hour follow-up. Task waiting starts at task admission instead. Late observations remain censored, not failures or convenient exclusions.</p></section></div><p>Safe domain labels group work rather than rank workers. Interface work is the largest selected domain; the mix makes this an appliance study, not a homogeneous benchmark.</p><p class=\"limit\">Historical identity and vocabulary may be migration-normalized. This is a replay of the frozen canonical evidence, not a recovered archive of every original envelope. Field-specific rules are in the provenance table.</p><p class=\"evidence\">Q01 · Q03–Q05 · Q09 · Q18 · provenance</p>", charts::bars(q(p,"Q03"),None,public,"delivery-composition")?))));

    pages.push(("Operating map", page("Operating map / 02", "Authority crosses boundaries.", "<p class=\"lede\">The appliance coordinates work, admission and publication. Each boundary answers a different question; no one green light answers them all.</p><div class=\"mechanism\"><div><strong>Task journal</strong>What was admitted, claimed, phased, corrected or closed?</div><div><strong>Proof admission</strong>Which selected tree and declared obligations earned trusted credit?</div><div><strong>Git publication</strong>Which implementation head reached an integrated boundary?</div></div><div class=\"mechanism\"><div><strong>Steering</strong>Was a direction delivered and visibly acknowledged?</div><div><strong>Lane lifecycle</strong>Which stable lane carried which declared provider session?</div><div><strong>Running appliance</strong>Which implementation was actually activated?</div></div><div class=\"finding\"><strong>Keep the verbs literal.</strong> A task can be done in one phase but pending in its workflow. A recorded integration can exist without a separately dated activation observation. A session can survive repeated process starts.</div><div class=\"columns\"><section><h3>Policy / capability</h3><p>The following page locates two concrete integrated changes. Those boundaries partition the observation windows; they do not establish exposure to a running capability.</p></section><section><h3>Coverage / exposure</h3><p>Admission counts, phase mix, right-censoring and lifecycle attribution travel beside the outcomes. A release or lapse is a task-state observation, not a diagnosis of worker quality.</p></section></div><p class=\"limit\">The journal and Git preserve publication evidence. This study does not recover a complete build-identity-to-resident-activation chain. No timeline band is labeled activated.</p><p class=\"evidence\">E03 · E05 · Q05–Q07 · Q21–Q27</p>")));

    let policy = case(p, "E05")?;
    let refill = case(p, "E03")?;
    pages.push(("Integrated boundaries and exposure", page("Operating map / 03", "Integration is not activation.", &format!("<p class=\"lede\">Two recorded changes make useful observation boundaries. They are not a randomized intervention and do not isolate a single cause.</p><div class=\"timeline\"><section><p class=\"date\">{} · PRE-POLICY</p><h3>Opening observation window</h3><p>The study begins at its earliest selected delivery. Historical closure routes and retained opening context remain eligible evidence.</p></section><section><p class=\"date\">{} · {} · POLICY TO REFILL</p><h3>Blocking-policy integration</h3><p>The implementation fact records an integrated boundary. A later clean verdict closes the task. The running appliance's activation time is not established by either.</p></section><section><p class=\"date\">{} · {} · POST-REFILL</p><h3>Timestamp-preserving materialization</h3><p>A recorded mechanism avoids rewriting unchanged staged files. Its bounded experiment belongs to the proof spread, not to a fleet-wide causal estimate.</p></section></div>{}<p class=\"limit\">The short window names in charts mean before policy integration, policy integration to refill integration, and after refill integration. They abbreviate recorded boundaries, not activation regimes. Phase composition differs substantially across windows.</p><p class=\"evidence\">{} · {} · Q07 · complete ordered cases in tables.html</p>", p.first_delivery_day, integration_day(policy)?, policy.id, integration_day(refill)?, refill.id, table(q(p,"Q07"),None), policy.id, refill.id))));

    pages.push(("Common-follow-up landing outcomes", page("Landing / 04", "Same follow-up. Different mix.", &format!("<p class=\"lede\">Every eligible admission stays in the 24-hour denominator. Outcomes are first phase boundaries, not eventual workflow deliveries.</p>{}<div class=\"columns\"><section><h3>What changes visibly</h3><p>The post-refill todo window records 450 phase completions among 491 eligible admissions; the policy-to-refill window records 470 among 697. The pre-policy todo window records 488 among 605. These counts describe the admitted work, not a treatment effect.</p></section><section><h3>What keeps it honest</h3><p>The legacy implementation label has only five eligible episodes. Plans and todos are separate. Late admissions are reported as censored; missing-history episodes would remain explicit rather than becoming successes.</p></section></div><p class=\"limit\">Completion, release, lapse, deletion and derived different-lane transfer are distinct first outcomes. Same-lane carries and rebounds preserve the claim episode. Overlapping operational changes, changing task mix and migration-normalized provenance rule out a causal speedup claim.</p><p class=\"evidence\">Q05–Q07 · eligibility, ordered outcome counts and exposure tables</p>", charts::outcomes(p,public,"phase-outcomes")?))));

    pages.push(("Waiting and held time", page("Landing / 05", "Queue time is not held time.", &format!("<p class=\"lede\">Separate clocks prevent a faster queue from becoming an unsupported claim of faster implementation.</p>{}{}<div class=\"columns\"><section><h3>Waiting conditions</h3><p>Task admission to first claim, for eligible admissions with a claim inside 24 hours. Q09 keeps the 29 no-first-claim observations and 81 late admissions visible. These are not medians for all arrivals.</p></section><section><h3>Holding conditions</h3><p>Canonical claim to first terminal boundary, within the same follow-up. Renewals and same-lane occupant changes are continuity, not new episodes. Held wall time is neither active labor nor CPU time.</p></section></div><p class=\"limit\">Minutes. Each row carries its sample size. Quantiles use the higher empirical order statistic at zero-based rank ceil((n−1)p), without interpolation. Small legacy groups are observations, not trend estimates.</p><p class=\"evidence\">Q08–Q10 · full definitions, censoring and clock exclusions</p>", distribution(q(p,"Q08"))?, distribution(q(p,"Q10"))?))));

    pages.push(("Incomplete work and inter-claim gaps", page("Landing / 06", "The unfinished denominator matters.", &format!("<p class=\"lede\">A completion-selected story omits the work that did not complete. The admission view puts it back.</p>{}{}<div class=\"columns\"><section><h3>Withdrawals are not deliveries</h3><p>Deletion before a first claim and deletion after a recorded claim have different histories. Hidden friction is not exported as public work. Retained legacy friction rows are excluded from waiting and withdrawal rates, not silently turned into ordinary arrivals.</p></section><section><h3>Gaps are separate again</h3><p>A successor claim can follow a known predecessor boundary immediately or much later. Missing predecessors do not become zero-duration gaps. The table conditions on successive same-task episodes with an eligible later admission.</p></section></div><p class=\"finding\">Six public non-friction admissions remain incomplete at the horizon. Delivered fixes elsewhere do not establish that every navigation or operational problem was resolved.</p><p class=\"evidence\">Q11 · Q18 · complete task support, including selected flags and closure routes</p>", table(q(p,"Q18"),None), distribution(q(p,"Q11"))?))));

    pages.push(("First verdict and eventual closure", page("Correction circuit / 07", "Final clean is not first-pass clean.", &format!("<p class=\"lede\">The first verdict is assigned at its own boundary. Later clean closure does not rewrite it.</p>{}<div class=\"stats\"><div class=\"stat\"><strong>{}</strong><span>selected deliveries with verdicts · Q13</span></div><div class=\"stat\"><strong>{}</strong><span>ever had a finding · Q14</span></div><div class=\"stat\"><strong>{}</strong><span>no recorded verdict · Q12</span></div></div><p>First findings appear in every observation window. First-clean and first-finding histories therefore remain separate even where a task's final selected route is clean review.</p><p class=\"limit\">The cohort conditions on completion at the horizon. It is not an estimate of future review success for all admitted tasks. Historical terminal findings remain their own closure route; the legacy review-phase-done case has no verdict.</p><p class=\"evidence\">Q02 · Q12–Q14 · E02</p>", charts::bars(q(p,"Q12"),None,public,"first-review-verdict")?, q(p,"Q13").denominator, value(p,"Q14","Any recorded finding"), value(p,"Q12","No recorded review verdict")))));

    pages.push(("Rounds, corrections and attribution", page("Correction circuit / 08", "Order survives the final head.", &format!("<p class=\"lede\">Review histories include repeated verdicts, correction births and re-review. They are not reconstructed from today's clean head.</p>{}{}<div class=\"columns\"><section><h3>Actual phase authors</h3><p>Each verdict is joined to the preceding completed non-review phase author, not to the task's creator. The study records {} same-lane and {} different-lane verdicts. Different lane does not prove different human judgment or model independence.</p></section><section><h3>Requested versus resulting flow</h3><p>Journal flow says what the correction task carried. It does not universally say what the request explicitly asked for. E01 has an additional retained command record proving its implementation-only operand.</p></section></div><p class=\"limit\">Correction-flow rows are recorded task flows, not a recovered request ledger. Deleted, unavailable and publication-inadmissible relationships cannot be invented from prose.</p><p class=\"evidence\">Q13 · Q15–Q16 · E01 · campaign relationship alternatives</p>", charts::bars(q(p,"Q13"),None,public,"ordered-review-rounds")?, table(q(p,"Q16"),None), value(p,"Q15","Same lane"), value(p,"Q15","Different lane")))));

    pages.push(("Ordered correction case", correction));

    pages.push(("Historical closure inventory", page("Correction circuit / 10", "Preserve the route that happened.", &format!("<p class=\"lede\">Modern clean-only intuition is not a historical replay rule.</p>{}{}<p>A done fact closes the current phase. Whether it ends the workflow depends on the recorded flow and later state transitions. A terminal historical finding can count as completion without being relabeled clean; later reopening invalidates that completed episode.</p><p class=\"limit\">Operator closure is an explicit route with zero selected occurrences here. Zero is reported, not dropped. The legacy review-phase-done case remains distinct from ordinary no-review completion.</p><p class=\"evidence\">E02 · Q02 · selected task support and historical reconstruction receipt</p>", table(q(p,"Q02"),None), case_html(case(p,"E02")?)))));

    pages.push(("Recorded materialization experiment", page("Proof / 11", "Avoid rewriting unchanged bytes.", &format!("<p class=\"lede\">A small mechanism claim is stronger than an invented fleet performance claim.</p>{}{}<div class=\"columns\"><section><h3>Recorded conditions</h3><p>The same packages, target directory and machine. Fresh materialization, unchanged refill and a three-file change. These are historical recorded measurements, not newly run benchmarks.</p></section><section><h3>What actually changed</h3><p>Refill writes changed bytes, removes unselected paths and leaves unchanged files untouched. That preserves the timestamps Cargo uses to decide whether source is newer than its artifacts.</p></section></div><p class=\"limit\">The source record rejects the initial path-location premise: changing absolute workspace location with preserved times was not the expensive arm. The report does not generalize these three measurements to every task, era or machine.</p><p class=\"evidence\">E03 · Q19–Q20 · exact original commit body retained privately</p>", charts::bars(q(p,"Q19"),None,public,"recorded-materialization-seconds")?, charts::bars(q(p,"Q20"),None,public,"recorded-materialization-crates")?))));

    pages.push(("Proof credit and bounded validation", page("Proof / 12", "Reuse credit. Keep the obligation.", &format!("<p class=\"lede\">Proof credit belongs to a selected identity and declared obligations, not to a worker's memory of a green run.</p><div class=\"mechanism\"><div><strong>Selected identity</strong>The tree and semantic inputs determine what a receipt may admit.</div><div><strong>Trusted evidence</strong>Sealing and object-identity verification still apply to a refilled tree.</div><div><strong>Validation bounds</strong>Root admission, compiler jobs and test workers are different limits.</div></div><div class=\"columns\"><section><h3>Coarse shards</h3><p>A shard's scheduling granularity is separate from per-compiler or per-test worker counts. Bounding one dimension does not establish a bound on the whole process family. This is mechanism reading, not measured CPU utilization.</p></section><section><h3>Materialization integrity</h3><p>The recorded refill mechanism holds possession while a run measures the tree, seals the selected identity and verifies object identity. Avoided copies or recompiles are not waived validation obligations.</p></section></div>{}<p>Only retained proof-seal observations support this inventory. There is no complete historical denominator for receipt reuse, validation commands or proof cost in this snapshot. Missing or GC-censored records do not become zero cost.</p><p class=\"limit\">Do not combine the materialization experiment with admission outcomes to manufacture a causal efficiency number. There is no measured whole-era speedup claim in this guide.</p><p class=\"evidence\">E03 · Q19–Q20 · Q30 · pinned source and recorded experiment</p>", table(q(p,"Q30"),None)))));

    pages.push(("Continuity identities", page("Continuity / 13", "A lane is not a process start.", &format!("<p class=\"lede\">Stable lanes, declared provider sessions, occupants and lifecycle events have different grains.</p>{}<div class=\"mechanism\"><div><strong>Lane · L</strong>Stable coordination identity across claim renewal and process lifecycle.</div><div><strong>Session · S</strong>Recorded lane/vendor/provider-session identity tuple; not every declaration.</div><div><strong>Configuration · C</strong>Observed declaration or retune, not today's setting projected backward.</div></div><div class=\"columns\"><section><h3>Declarations repeat</h3><p>The same provider-session identity can be declared again and participate in several process starts or compactions. Those events are not new workers.</p></section><section><h3>Occupants can change</h3><p>Same-lane carries and rebounds preserve a claim episode while updating the occupant. An occupant-only lapse is joined to its recorded claimant, not guessed from the current lane.</p></section></div><p class=\"limit\">Session span endpoints are first and last retained observations. They are not proved activation or termination times. Configuration aliases distinguish observations without implying equivalent models or providing a model leaderboard.</p><p class=\"evidence\">Q21–Q23 · complete session and configuration alternatives</p>", table(q(p,"Q21"),None)))));

    pages.push(("Continuity and operational handoff", page("Continuity / 14", "Exposure does not rank workers.", &format!("<p class=\"lede\">Held wall time is attached to stable lane identity. It is not a measure of attention, skill or compute.</p>{}<div class=\"columns\"><section><h3>Recorded lifecycle</h3><p>Q22 contains {} compaction events and {} retunes inside the delivery window. Q23 names {} events without a single resolvable session attribution. Missing attribution is not filled from current configuration.</p></section><section><h3>A concrete handoff</h3><p>E04 crosses from filing lane L038 to implementation lane L036. L036 also records the clean review. The work crossed lanes; implementation and review in this case did not.</p></section></div><p>The full alternatives preserve all observed lanes and provider-session strips, including lanes omitted from this identity-ordered panel. Repeated starts and exits remain event counts, not session counts.</p><p class=\"limit\">The delivered-key recognition fix does not prove that every operational issue was resolved. Six incomplete admitted tasks remain in the horizon inventory. This is continuity evidence, not a best-worker ranking.</p><p class=\"evidence\">E04 · Q18 · Q21–Q24 · complete lane/session alternatives</p>", charts::continuity(p,public,"lane-exposure")?, value(p,"Q22","lane::compacted"), value(p,"Q23","Observed in-window retunes"), value(p,"Q23","Unattributed lifecycle events")))));

    pages.push(("Bounded campaign layers", page("Campaign / 15", "Three relations. One node set.", &format!("<p class=\"lede\">Origins, blocking dependencies and corrections are different relations. None is phase authorship.</p>{}<p class=\"scope\">{} displayed nodes; {} omitted public campaign nodes. Edge frontiers and complete node/edge alternatives are separate. The bound is editorial, not a change to delivery membership.</p><p class=\"limit\">Authors label recorded non-review completions, not exclusive ownership. Origins and dependencies use independent horizon board statements; findings supply correction requests. Edited envelopes alone cannot recover historical statement arrays. Publication-inadmissible context is not expanded into a hidden graph.</p><p class=\"evidence\">Q28–Q29 · campaign node, edge and frontier alternatives</p>", charts::campaign(p,public,"campaign-layers")?, p.campaign.nodes.len(), p.campaign.omitted_public_nodes))));

    pages.push(("Git concordance", page("Landing boundary / 16", "The fact head comes first.", &format!("<p class=\"lede\">Trailers corroborate a task join. They do not replace its recorded implementation boundary or prove exclusive ownership.</p>{}{}{}<div class=\"columns\"><section><h3>Exact object joins</h3><p>All referenced objects in this frozen context are available. Curated E01, E03, E04 and E05 joins use real merge parents and first-parent-to-second-parent contribution ranges. Their implementation heads are actual merge parents and ancestors, not a later review head.</p></section><section><h3>Honest trailer coverage</h3><p>Missing or disagreeing head trailers stay named. Plan-phase context can have a prior implementation head; therefore concordance covers completed non-review phase heads, not an exclusive authorship inventory.</p></section></div><p class=\"limit\">An integrated boundary observed at done does not separately date done-to-integration latency. No such interval is estimated. Git timestamps cannot date migration execution or appliance activation.</p><p class=\"evidence\">Q25–Q27 · curated Git alternatives · original objects and metadata retained privately</p>", table(q(p,"Q25"),None), table(q(p,"Q26"),None), table(q(p,"Q27"),None)))));

    pages.push(("Evidence strength and provenance", page("Limits / 17", "Normalized is not untouched.", "<p class=\"lede\">The saved evidence is reproducible. Its older rows are not universally original event-time bytes.</p><div class=\"table-wrap\"><table><caption>How to read the evidence classes</caption><thead><tr><th scope=\"col\">Class</th><th scope=\"col\">Supports</th><th scope=\"col\">Does not support</th></tr></thead><tbody><tr><th scope=\"row\">Frozen typed facts</th><td>Canonical order, retained event fields, historical state transitions</td><td>A claim that all retained spellings predate every migration</td></tr><tr><th scope=\"row\">Independent horizon census</th><td>Distinct cohort reconciliation and horizon statements</td><td>Unrecorded intermediate statement revisions</td></tr><tr><th scope=\"row\">Retained command record</th><td>Explicit correction operand in E01</td><td>A complete uncensored request ledger</td></tr><tr><th scope=\"row\">Exact Git objects</th><td>Recorded publication joins, parent topology and curated source record</td><td>Runtime activation, migration execution time or exclusive ownership</td></tr><tr><th scope=\"row\">Report-derived quantities</th><td>Named populations, denominators, ordered reductions and aggregate distributions</td><td>Causal improvement, CPU utilization or worker/model superiority</td></tr></tbody></table></div><div class=\"columns\"><section><h3>Known applicability</h3><p>Task identities contract from historical handles; vocabulary is normalized; claim-time allocation and creation context can be reconstructed by migrations. Field-specific source modules and schema steps are in the complete provenance table.</p></section><section><h3>Known absence</h3><p>There is no general per-row migration execution audit or pre-migration envelope archive. Source integration dates do not establish which day a migration ran against a particular row.</p></section></div><p class=\"limit\">Decoder/schema generation, frozen bytes, consumer and rule digests are pinned privately. Later-schema re-export is not assumed equivalent. Missing, censored and potentially reconstructed evidence remain named limitations, not repaired history.</p><p class=\"evidence\">provenance · cohort reconciliation · private snapshot manifest</p>")));

    pages.push(("Offline bundle and reproduction", page("Publication / 18", "Share the guide. Keep the originals separate.", "<p class=\"lede\">The offline reader receives the entire sanitized argument and its support—not credentials or promises of restricted source access.</p><div class=\"bundle\"><h3>Publication bundle</h3><ul><li>index.html — semantic narrative, local fonts and vector figures</li><li>making-work-land.pdf — selectable portrait print edition</li><li>tables.html — every quantity, graph alternative, lane/session strip and task support row</li><li>data.json, measurements.csv, tasks.csv — the same allowlisted analytical records</li><li>assets/ — deterministic SVGs, unmodified licensed fonts and license texts</li><li>manifest.json — content digests and the observed local print boundary</li></ul></div><div class=\"columns\"><section><h3>Private evidence</h3><p>Exact identities, source positions, precise instants, the command operand record, Git objects and provenance maps remain outside the publication tree. The saved one-off consumer belongs there too, not in the product's editorial API.</p></section><section><h3>Reproduction boundary</h3><p>Reacquisition uses the admitted native fixed-horizon reader, with bounded pages and a decoder/schema/residency pin. Rendering reuses the saved snapshot through one pinned local Chromium boundary. Re-export is not a substitute for the saved normalized bytes.</p></section></div><p class=\"limit\">Overview instants are day-coarsened; curated cases use hours. Minute-scale durations are aggregate distributions. Precise seconds belong only to the attributed recorded experiment. No raw task, lane, session, Git or machine identity is part of the shareable bundle.</p><p class=\"evidence\">Public manifest · complete support · separate private reproduction record</p>")));

    pages.push(("What this study establishes", page("Reading the result / 19", "Landing needs several kinds of evidence.", &format!("<p class=\"lede\">The result is not one efficiency score. It is a set of observable boundaries that must not be collapsed.</p><ol class=\"steps\"><li><strong>Completion has a historical route.</strong> {} selected deliveries close through clean review; {} close through a historically terminal finding. Ordinary flow-ending done and legacy review-phase done remain distinct. Q02.</li><li><strong>Corrections survive clean closure.</strong> {} selected reviewed deliveries have at least one finding. First verdicts, correction flows and ordered rounds retain that history. Q12–Q16.</li><li><strong>Comparisons need exposure.</strong> {} eligible phase admissions share 24-hour follow-up; {} late admissions remain censored. Phase composition and conditional waiting distributions prevent a casual before/after efficiency claim. Q05–Q10.</li><li><strong>A mechanism can stand on narrow evidence.</strong> The recorded unchanged refill avoided recompilation without weakening sealing or verification. The three historical arms do not prove a fleet speedup. E03, Q19–Q20.</li><li><strong>Continuity has several identities.</strong> Stable lanes, provider-session spans and occupants cannot be counted as interchangeable workers. Filing, phase authorship and review are separate. E04, Q21–Q24.</li></ol><div class=\"finding\"><strong>The useful conclusion:</strong> treat delivery, proof admission, integration and operational continuity as separate evidence-bearing transitions. A final label alone is too small a record.</div><p class=\"limit\">No activation chain, causal speedup, model ranking, exclusive code ownership or independent-review guarantee is inferred. The complete offline tables preserve the quantities even where the observation is no improvement or incomplete work.</p><p class=\"evidence\">Q01–Q30 · E01–E05 · complete sanitized support</p>", value(p,"Q02","clean review"), value(p,"Q02","historically terminal finding"), value(p,"Q14","Any recorded finding"), q(p,"Q06").denominator, value(p,"Q05","Late, right-censored")))));
    Ok(pages)
}

fn page(kicker: &str, title: &str, body: &str) -> String {
    format!(
        "<p class=\"kicker\">{}</p><h2>{}</h2>{body}",
        escape(kicker),
        escape(title)
    )
}

fn case<'a>(publication: &'a Publication, id: &str) -> Result<&'a super::super::Case> {
    publication
        .cases
        .iter()
        .find(|case| case.id == id)
        .ok_or_else(|| format!("curated case missing: {id}").into())
}

/// The day a curated case recorded its implementation boundary.
fn integration_day(case: &super::super::Case) -> Result<&str> {
    case.steps
        .iter()
        .find(|step| step.action == "phase done")
        .and_then(|step| step.hour.split_once(' '))
        .map(|(day, _)| day)
        .ok_or_else(|| format!("curated case {} lacks an implementation boundary", case.id).into())
}

fn distribution(quantity: &Quantity) -> Result<String> {
    if quantity.group_samples.is_empty() {
        return Ok(format!(
            "<p>{}: no covered distribution; absence is not zero duration.</p>",
            quantity.id
        ));
    }
    let values = quantity
        .values
        .iter()
        .map(|row| (row.label.as_str(), row.value))
        .collect::<BTreeMap<_, _>>();
    let mut html = format!(
        "<div class=\"table-wrap\"><table><caption>{} · {} · minutes</caption><thead><tr><th scope=\"col\">Integration window / phase</th><th scope=\"col\" class=\"numeric\">n</th><th scope=\"col\" class=\"numeric\">Median</th><th scope=\"col\" class=\"numeric\">p90</th><th scope=\"col\" class=\"numeric\">p95</th></tr></thead><tbody>",
        quantity.id,
        escape(&quantity.name)
    );
    for (group, count) in &quantity.group_samples {
        let mut row_values = [0.0; 3];
        for (index, label) in ["median", "p90", "p95"].into_iter().enumerate() {
            row_values[index] = *values
                .get(format!("{group} / {label}").as_str())
                .ok_or("distribution sample group lacks its quantile")?;
        }
        let label = group
            .replace("Before blocking-policy integration", "Pre-policy")
            .replace("After blocking-policy integration", "Policy to refill")
            .replace("After materialization integration", "Post-refill");
        html.push_str(&format!("<tr><th scope=\"row\">{}</th><td class=\"numeric\">{count}</td><td class=\"numeric\">{}</td><td class=\"numeric\">{}</td><td class=\"numeric\">{}</td></tr>",escape(&label),number(row_values[0]),number(row_values[1]),number(row_values[2])));
    }
    html.push_str("</tbody></table></div>");
    Ok(html)
}
